// words and abbreviations ("ad hoc", "120 bp" basis points, "ah"). BCE precedes
// BC so the longer marker wins the alternation.
const ERA_MARKER_UPPER = '(?:AD|BCE|BC|CE|AH|BP)';
// A marker with periods matches in any case ("A.D.", "a.d.", "B.C.E."). Each
// form requires at least its first period, so a marker with no period matches
// ERA_MARKER_UPPER alone.
const ERA_MARKER_DOTTED = '(?:[Aa]\\.[Dd]\\.?|[Bb]\\.[Cc]\\.[Ee]\\.?|[Bb]\\.[Cc]\\.?|[Cc]\\.[Ee]\\.?|[Aa]\\.[Hh]\\.?|[Bb]\\.[Pp]\\.?)';
const ERA_MARKER = '(?:' + ERA_MARKER_UPPER + '|' + ERA_MARKER_DOTTED + ')';
// Both orders take the same rules: the space between the year and the era
// marker is optional, the digits are not part of a larger number (no digit or
// decimal mark on the side away from the marker), and the era marker is a
// standalone token (no letter on its far side, so "ADELAIDE", "ADD", and
// "DEAD" never match). No 'i' flag, for ERA_MARKER_UPPER.
// "<year> <era>": "2898 AD".
const ERA_YEAR_AFTER_RE = new RegExp('(?<![\\d.])(?<year>\\d[\\d,]*)\\s*' + ERA_MARKER + '(?![A-Za-z])', 'gd');
// "<era> <year>": "AD 79".
const ERA_YEAR_BEFORE_RE = new RegExp('(?<![A-Za-z])' + ERA_MARKER + '\\s*(?<year>\\d[\\d,]*)(?![\\d,]*(?:\\d|\\.\\d))', 'gd');

/**
 * Return {start, end} ranges (offsets into `text`) of every digit run that
 * forms a calendar year bound to an era marker, in either order ("2898 AD" or
 * "AD 79").
 */
function getEraYearMaskedRanges(text) {
  return [ERA_YEAR_AFTER_RE, ERA_YEAR_BEFORE_RE].flatMap((re) => matchRanges(text, re, 'year'));
}

// ---- chrome-extension/lib/dr-number/write-back.js ----

// Copyright (c) 2026 Arie Fisher | SPDX-License-Identifier: MIT
/**
 * The write-back: turning a rounded value back into text. Reads no page and
 * calls no Chrome.
 */

/**
 * The Intl formatter every rounded value is written with. It is built once,
 * because a toLocaleString call with options builds a new formatter on every
 * call, which took most of a pass's time. useGrouping stays explicit so the
 * grouping does not depend on the engine's default.
 */
const GROUPED_NUMBER_FORMAT = new Intl.NumberFormat('en-US', {
  maximumFractionDigits: 10,
  useGrouping: true,
});

/**
 * The result replaces a number's digits in place, for every cell. Its marks
 * are the ones the number format function (reader.js) returns.
 *
 * The characters around the number stay where the source put them, so a minus
 * sign is written only when originalNumStr itself starts with one. A negative
 * whose number holds no minus sign carries its sign outside the patched
 * characters: in the brackets around it (see isBracketedNegative), or in a
 * pure cell's own leading sign (see pureNumberSpan). A minus written here
 * would double that sign ("(-1,200)").
 */
function formatNumber(rounded, originalNumStr) {
  const marks = numberFormat();
  const signed = originalNumStr.startsWith('-') ? rounded : Math.abs(rounded);
  return GROUPED_NUMBER_FORMAT.format(signed)
    .replace(/[,.]/g, (mark) => (mark === ',' ? marks.group : marks.decimal));
}

// ---- chrome-extension/lib/dr-number/identifiers.js ----

// Copyright (c) 2026 Arie Fisher | SPDX-License-Identifier: MIT

/**
 * Identifier shapes: text shapes that read as a code rather than a quantity —
 * a phone number, an IP address, a web or email address, an ISBN, a postal
 * code, a digit run with a leading zero, or digit groups split by whitespace
 * outside thousands grouping.
 *
 * One check finds every code in a cell: findIdentifiers searches the cell's
 * text once for every shape and records, for each code it finds, whether the
 * code fills the cell. A code fills the cell when nothing stands around it
 * but the format marks, signs, and brackets the number span of a pure cell
 * steps past (PURE_LEAD_PATTERN and PURE_TRAIL_PATTERN in
 * numbers-in-text.js), so "(416) 555-1234" and "$ 416-555-1234" fill their
 * cells. A text in thousands
 * grouping ("1 234 567 890") is a quantity, and no code fills it.
 *
 * The ladder reads the result three ways. isWebOrEmailAddressCell runs the
 * web-or-email shape alone, and classifyCell (lib/dr-simplify/ladder.js)
 * gives a cell that address fills no stretch, before the date and time
 * readers, so a date in an address's path stays as written.
 * matchIdentifierShape returns the name of a code that fills the cell, and
 * classifyCell gives that cell no stretch in a cell that holds no date or
 * time, so a date the date parser reads ("21 June 2020") stays a date, and
 * before the number reader. getIdentifierMaskedRanges
 * returns the codes that count inside a cell with words ("Call 416-555-1234
 * about 1,613,245 units"), and extractSimplifyMatches drops every number
 * inside one, so the code stays as written and the other numbers round.
 *
 * Some codes count only when they fill the cell, because inside a sentence
 * the same characters are as likely to be several numbers: digit groups
 * split by spaces alone ("in 2024 12 stores" holds two numbers), and an ISBN
 * without the word "ISBN".
 *
 * Every repeat in every pattern matches each character one way only, a code
 * inside text starts only where a shape can start, and every test of the
 * text around a code is anchored at both ends, so every test runs in time
 * linear in the text's length. findIdentifiers lists the text's number runs
 * once for a shape marked groupOfNumber and steps through that list once, so
 * the test for a group of a longer number reads the text once, not once for
 * each code.
 *
 * Each shape's pattern comes first; the list, the one search, and its two
 * readings close the file.
 *
 * Loaded by manifest content_scripts AFTER lib/dr-number/numbers-in-text.js,
 * whose two patterns build the fill tests here at load time, and BEFORE
 * lib/dr-number/index.js; see its header. The Sheets build joins the files in
 * the same order. All symbols
 * land on the shared global scope, the same convention every other
 * lib/dr-number file uses.
 */

// Where a shape inside text may start and end: not right after a letter, a
// digit, an underscore, or a dot, and not right before a letter, a digit, an
// underscore, or a dot followed by one. So "12416-555-1234" and
// "192.168.0.1.5" hold no shape, and a sentence's closing period after one
// ("call 416-555-1234.") still ends it.
const SPAN_START = '(?<![\\w.])';
const SPAN_END = '(?![\\w]|\\.\\w)';
// A code made of digits, whitespace, and "+" alone, with at least one
// whitespace, is digit groups split by spaces, which count only when they
// fill the cell. A digit run with a leading zero holds no whitespace, so it
// counts inside text.
const SPACED_DIGITS_ONLY_RE = /^(?=.*\s)[+\d\s]+$/;

// A code found anywhere inside text between the edges above.
const spanRe = (pattern, flags = '') => new RegExp(`${SPAN_START}(?:${pattern})${SPAN_END}`, `${flags}g`);
// The text before and after a code that fills its cell, and a pattern that
// fills the cell on its own.
const CELL_LEAD_RE = new RegExp(`^${PURE_LEAD_PATTERN}$`);
const CELL_TRAIL_RE = new RegExp(`^${PURE_TRAIL_PATTERN}$`);
const fillingRe = (pattern, flags = '') => new RegExp(`^${PURE_LEAD_PATTERN}(?:${pattern})${PURE_TRAIL_PATTERN}$`, flags);

// --- Phone numbers ---
// Two written shapes: digits split by dashes, dots, or spaces in a 3-3-4
// group with an optional leading "1" or "+1" ("416-555-1234", "416.555.1234",
// "416 555-1234", "1-800-555-0199"), or a bracketed area code with the same
// optional lead and an optional space after the bracket ("(416) 555-1234",
// "(416)555-1234", "(416) 555 1234", "+1 (416) 555-1234"). "100-200" is two
// groups, not three, so it is not this shape and keeps rounding as an
// extracted cell.
const PHONE_NUMBER_PATTERN = '\\+?(?:1[-.\\s]?)?\\d{3}[-.\\s]\\d{3}[-.\\s]\\d{4}|(?:\\+?1[-.\\s]?)?\\(\\d{3}\\)\\s?\\d{3}[-.\\s]\\d{4}';

// --- Grouped digits split by whitespace ---
// A digit run split by whitespace reads as thousands grouping only in the
// group shape (groupShapePattern, reader.js, the one copy the number shape
// test reads too), with an optional decimal part glued to the last group
// ("1 234 567", "12 345.67"). Anything else with whitespace between two
// digits — a first group over 3 digits, a later group not exactly 3 — is not
// that shape, so it reads as an identifier instead of a quantity. It counts
// only when it fills the cell, and only when the cell's digits sit in one
// text piece: a cell with "1500" above "1600" in separate pieces joins its
// pieces with whitespace, and that join is several numbers, not one spaced
// identifier.
const GROUPED_DIGITS_RE = fillingRe('\\d+(?:\\s+\\d+)+(?:\\.\\d+)?');
const GROUPED_DIGITS_QUANTITY_RE = fillingRe(groupShapePattern(GROUP_SPACE_PATTERN) + '(?:\\.\\d+)?');

// --- IP addresses ---
// IPv4: four dot-separated groups, each 0-255. "192.5" and "1.5" are two
// groups, not four, so they are not this shape and keep rounding as plain
// numbers. IPv6: hex groups joined by colons, with "::" standing for one run
// of zero groups. The time check earlier in the ladder already reads a plain
// "12:30:45" as a time, so the whole-cell test only ever sees what that
// check left behind, and inside text no IPv6 shape short of eight groups
// matches without a "::".
const IPV4_OCTET = '(?:25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)';
const IPV4_PATTERN = `${IPV4_OCTET}\\.${IPV4_OCTET}\\.${IPV4_OCTET}\\.${IPV4_OCTET}`;
// The eight standard IPv6 group shapes (full form, and every placement of one
// "::" run), each built from bounded repeats of a fixed hex-group-plus-colon
// atom — no group repeats another repeating group, so matching stays linear.
const IPV6_PATTERN = '(?:' + [
  '(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}',
  '(?:[0-9a-fA-F]{1,4}:){1,7}:',
  '(?:[0-9a-fA-F]{1,4}:){1,6}:[0-9a-fA-F]{1,4}',
  '(?:[0-9a-fA-F]{1,4}:){1,5}(?::[0-9a-fA-F]{1,4}){1,2}',
  '(?:[0-9a-fA-F]{1,4}:){1,4}(?::[0-9a-fA-F]{1,4}){1,3}',
  '(?:[0-9a-fA-F]{1,4}:){1,3}(?::[0-9a-fA-F]{1,4}){1,4}',
  '(?:[0-9a-fA-F]{1,4}:){1,2}(?::[0-9a-fA-F]{1,4}){1,5}',
  '[0-9a-fA-F]{1,4}:(?::[0-9a-fA-F]{1,4}){1,6}',
  ':(?:(?::[0-9a-fA-F]{1,4}){1,7}|:)',
].join('|') + ')';
const IP_ADDRESS_PATTERN = `${IPV4_PATTERN}|${IPV6_PATTERN}`;

// --- Web and email addresses ---
// A URL prefix (http://, https://, www.) followed by anything non-blank, or
// a bare name@domain.tld shape. The domain's labels exclude the dot that
// joins them, so each character has one place to match. An email address
// starts only after whitespace or at the text's start: its name part takes
// any non-blank character, so inside text a start at every punctuation mark
// of a long unbroken string would read that string again from each one. A
// whole cell starts at the text's start, so that edge never narrows it.
const WEB_PATTERN = 'https?:\\/\\/\\S+|www\\.\\S+';
const EMAIL_PATTERN = '[^\\s@]+@[^\\s@.]+(?:\\.[^\\s@.]+)+';
const WEB_OR_EMAIL_PATTERN = `${WEB_PATTERN}|(?<!\\S)(?:${EMAIL_PATTERN})`;

// --- ISBN-10 and ISBN-13 ---
// An optional "ISBN" word (with an optional "-10"/"-13" and an optional
// colon), then the digits with at most one dash or space between any two: 13
// digits starting 978 or 979 (ISBN-13), or 9 digits and a final digit or X
// (ISBN-10). Counting digits with an optional separator between each, rather
// than one pattern per grouping, covers every real grouping style
// (registration-group and publisher-prefix lengths vary by country and
// imprint) without hardcoding one. Without the "ISBN" word the digits must
// carry a dash or a space, the way an ISBN is printed: a bare 10- or
// 13-digit run ("1234567890") is a quantity written without thousands
// commas, and keeps rounding. An ISBN with the word counts anywhere; one
// without it counts only when it fills the cell.
// The colon takes the whitespace before it, so a run of whitespace after the
// word has one way to match.
const ISBN_PREFIX_PATTERN = 'isbn(?:-1[03])?(?:\\s*:)?\\s*';
const ISBN_BODY_PATTERN = '97[89](?:[- ]?\\d){10}|\\d(?:[- ]?\\d){8}[- ]?[\\dX]';
const ISBN_WITHOUT_WORD_RE = fillingRe(`(${ISBN_BODY_PATTERN})`, 'i');

// --- Postal codes ---
// Canadian (letter-digit-letter, digit-letter-digit: "M5V 2T6"), UK (one or
// two letters, a digit, an optional letter or digit, digit, two letters:
// "SW1A 1AA", "M1 1AE"), and US ZIP+4 (five digits, a dash, four digits:
// "90210-1234"). A bare five-digit ZIP ("90210") matches none of these and
// keeps rounding as a plain number.
const POSTAL_CODE_PATTERN = [
  '[A-Za-z]\\d[A-Za-z]\\s?\\d[A-Za-z]\\d',
  '[A-Za-z]{1,2}\\d[A-Za-z\\d]?\\s?\\d[A-Za-z]{2}',
  '\\d{5}-\\d{4}',
].join('|');

// --- Leading zero ---
// A digit run that starts with "0" followed by another digit: "007",
// "01234", "0012345678". A quantity is not written with a leading zero, and
// a code, an account number, or a US ZIP code in New England ("02134")
// often is. "0", "0.5", and "0.0625" are not this shape, since a decimal
// mark follows their zero. The run carries no group mark and no decimal
// mark: a run followed by a comma or a dot and a digit ("0123.45",
// "012,345") is not this shape. A sentence's comma or period after the run
// ("ID 0000123, late") still ends it. A run that is one group of a larger
// number ("034" in "1,034" or "1 034 567") is not a code either: the shape
// is groupOfNumber, so findIdentifiers drops a match that sits inside a
// longer number run.
const LEADING_ZERO_PATTERN = '0\\d+(?![.,]\\d)';

// The {start, end} of every run the pattern that finds a number inside text
// (numbers-in-text.js) takes as one number, in text order. That pattern reads
// the one copy of a number's digit run (DIGIT_RUN_PATTERN), so a group of a
// space-grouped or comma-grouped number is never read a second way here. A
// run's span starts after its minus sign, because the sign is not part of a
// group ("-0123").
const numberRunSpans = (text) => Array.from(text.matchAll(NUMBER_IN_TEXT_REGEX_GLOBAL), (run) => ({
  start: run.index + (run[0].startsWith('-') ? 1 : 0),
  end: run.index + run[0].length,
}));

// The one list of identifier shapes. Each entry holds the shape's name, its
// pattern for a code anywhere in the text, and, for a shape with a form that
// counts only when it fills the cell, a test of the whole text for that form.
// The test takes the text and whether the cell's digits span several text
// pieces. A shape marked groupOfNumber drops a match that is one group of a
// longer number run. findIdentifiers reads the list alone, and a new shape
// is one more entry here. Phone numbers come before grouped digits so
// "416 555 1234" takes the phone name.
const IDENTIFIER_SHAPES = [
  { name: 'phone-number', span: spanRe(PHONE_NUMBER_PATTERN) },
  { name: 'grouped-digits', fillsOnly: (text, digitsSpanPieces) => !digitsSpanPieces && GROUPED_DIGITS_RE.test(text) },
  { name: 'ip-address', span: spanRe(IP_ADDRESS_PATTERN) },
  { name: 'web-or-email-address', span: spanRe(WEB_OR_EMAIL_PATTERN, 'i') },
  {
    name: 'isbn',
    span: spanRe(`${ISBN_PREFIX_PATTERN}(?:${ISBN_BODY_PATTERN})`, 'i'),
    fillsOnly: (text) => /[- ]/.test((ISBN_WITHOUT_WORD_RE.exec(text) || [])[1] || ''),
  },
  { name: 'postal-code', span: spanRe(POSTAL_CODE_PATTERN) },
  { name: 'leading-zero', span: spanRe(LEADING_ZERO_PATTERN), groupOfNumber: true },
];

/**
 * Every code in text, in list order: its shape's name, its {start, end} in
 * the flat-text positions extractNumbersInText reports, whether it fills the
 * cell, and whether it counts inside a cell with words. Codes from different
 * shapes may overlap.
 * @param {string} text
 * @param {boolean} [digitsSpanPieces] - true when the cell's digits sit in
 *   more than one text piece
 * @returns {{name: string, start: number, end: number, fillsCell: boolean, inText: boolean}[]}
 */
function findIdentifiers(text, digitsSpanPieces = false, shapes = IDENTIFIER_SHAPES) {
  if (typeof text !== 'string') return [];
  const quantity = GROUPED_DIGITS_QUANTITY_RE.test(text);
  const codes = [];
  for (const shape of shapes) {
    const matches = shape.span ? Array.from(text.matchAll(shape.span)) : [];
    const runs = shape.groupOfNumber && matches.length > 0 ? numberRunSpans(text) : [];
    // A shape's codes and the number runs both stand in text order and never
    // overlap, so the only run that can hold a code is the first run that ends
    // at or after the code, and the next code's run never lies before it. A
    // cell of thousands of dates holds thousands of leading-zero codes, and a
    // walk over every run for each code takes time that grows with the square
    // of the cell's length.
    let runIndex = 0;
    for (const match of matches) {
      const start = match.index;
      const end = start + match[0].length;
      while (runIndex < runs.length && runs[runIndex].end < end) runIndex += 1;
      const run = runs[runIndex];
      // A code inside a longer number run is one group of that number.
      if (run !== undefined && run.start <= start && run.end - run.start > end - start) continue;
      const fillsCell = !quantity
        && CELL_LEAD_RE.test(text.slice(0, start)) && CELL_TRAIL_RE.test(text.slice(end));
      codes.push({ name: shape.name, start, end, fillsCell, inText: !SPACED_DIGITS_ONLY_RE.test(match[0]) });
    }
    if (shape.fillsOnly && !quantity && shape.fillsOnly(text, digitsSpanPieces)) {
      codes.push({ name: shape.name, start: 0, end: text.length, fillsCell: true, inText: false });
    }
  }
  return codes;
}

/**
 * The name of the first code that fills the cell, or null. A text in
 * thousands grouping is a quantity, so a ten- or thirteen-digit value
 * written "1 234 567 890" never reads as an ISBN.
 * @param {string} text - cell text
 * @param {boolean} [digitsSpanPieces] - true when the cell's digits sit in
 *   more than one text piece
 * @returns {string|null}
 */
function matchIdentifierShape(text, digitsSpanPieces = false) {
  const code = findIdentifiers(text, digitsSpanPieces).find((c) => c.fillsCell);
  return code ? code.name : null;
}

const WEB_OR_EMAIL_SHAPES = IDENTIFIER_SHAPES.filter((shape) => shape.name === 'web-or-email-address');

// True when a web or email address fills the cell. It reads that one shape
// alone, so the ladder can run it on every cell before any date or time.
function isWebOrEmailAddressCell(text) {
  return findIdentifiers(text, false, WEB_OR_EMAIL_SHAPES).some((code) => code.fillsCell);
}

/**
 * The {start, end} ranges of every code that counts inside a cell with
 * words. extractSimplifyMatches drops a number that touches any.
 * @param {string} text
 * @returns {{start: number, end: number}[]}
 */
function getIdentifierMaskedRanges(text) {
  return findIdentifiers(text).filter((c) => c.inText).map(({ start, end }) => ({ start, end }));
}

// ---- chrome-extension/lib/dr-simplify/ladder.js ----

// Copyright (c) 2026 Arie Fisher | SPDX-License-Identifier: MIT

/**
 * The classification ladder: the ordered per-cell rules that determine
 * whether and how a cell simplifies. classifyTableCell (lib/dr-table) calls
 * classifyCell for the rounding pass, the lens preview, and the data test,
 * and the Sheets input step calls it for each text cell.
 *
 * Core layer: reads no page and calls no Chrome. classifyCell takes the
 * cell's text, its row and column, the range list parsed once per table, and
 * the simplification options, and returns its classification as data. In the
 * extension the text is the rendered text (the raw text when the rendered
 * text is empty) or a simplified cell's stored original; in Sheets it is the
 * cell value. Four more values come from the cell's source, and the caller
 * derives them: the markup ranges, the spans of the text that the source
 * marks as a link or as code (getMarkupRanges in lib/dr-table on a page, the
 * markdown adapter in the plugin); whether the cell holds a superscript; the
 * superscript spans in the text classifyCell reads (getSuperscriptRanges);
 * and whether the cell's digits sit in more than one text piece (from the
 * piece layout). The bare names the ladder calls come from the lib/dr-number
 * files, loaded ahead of this file.
 */

/**
 * True when trimmedText is a single balanced ASCII double-quoted span
 * spanning the entire cell (e.g. `"12345"`). Such cells are left untouched —
 * quoting is read as "treat this text literally," not as a number to round.
 */
function isWholeCellQuoted(trimmedText) {
  return trimmedText.startsWith('"') && trimmedText.endsWith('"') &&
    (trimmedText.match(/"/g) || []).length === 2;
}

/**
 * The text with each range blanked to spaces. The blanks keep every position
 * in place, so a position in the result is the same position in the text.
 */
function blankRanges(text, ranges) {
  if (ranges.length === 0) return text;
  // One array of the text's characters, not one copy of the text per range:
  // a cell holding thousands of dates would otherwise copy its text thousands
  // of times.
  const blanked = text.split('');
  ranges.forEach((r) => blanked.fill(' ', r.start, r.end));
  return blanked.join('');
}

/**
 * Every date and time in the text. Each reader reads the text with the spans
 * of the readers before it blanked, so a reader earlier in the list keeps
 * the characters it reads: an ISO date-time first, because findDates reads no
 * date followed by "T"; then findDates; then clock times, on the text with
 * each superscript span blanked too, so a footnote marker right after a time
 * ("18:30<sup>2</sup>") never joins its digits.
 */
function readDatesAndTimes(text, superscriptRanges) {
  const isoPairs = findISODateTimes(text);
  const dateText = blankRanges(text, isoPairs.map(({ date, time }) => ({ start: date.start, end: time.end })));
  const dates = findDates(dateText) || [];
  const times = findClockTimes(blankRanges(dateText, [...dates, ...superscriptRanges]));
  return { isoPairs, dates, times };
}

const valuesRead = ({ isoPairs, dates, times }) =>
  [...isoPairs.flatMap(({ date, time }) => [date, time]), ...dates, ...times];

/**
 * Every date and time in the text (readDatesAndTimes), with isHeld: true on
 * each one that overlaps a markup range. A value only partly inside a link
 * ("<a>Jan 15</a>, 2024") is held whole. A held value keeps its place in its
 * ISO date-time and among the cell's clock times, so the rules that read the
 * values together still see it (dateTimeStretches).
 *
 * findDates reads a bare year only when the text holds nothing else, so a
 * year beside a held date ("<a>2023-01-01</a> 2024") reads only once the held
 * values are blanked. That second read runs once: a bare year fills the text,
 * so no third value can follow it.
 */
function readDatesAndTimesHoldingMarkup(text, superscriptRanges, markupRanges) {
  const isInMarkup = (v) => overlapsMaskedRange(markupRanges, v.start, v.end);
  const mark = (v) => (isInMarkup(v) ? { ...v, isHeld: true } : v);
  const read = readDatesAndTimes(text, superscriptRanges);
  const values = valuesRead(read);
  const heldValues = values.filter(isInMarkup);
  const datesBesideHeld = heldValues.length === 0 ? [] : (findDates(blankRanges(text, heldValues)) || [])
    .filter((d) => !overlapsMaskedRange(values, d.start, d.end));
  return {
    isoPairs: read.isoPairs.map(({ date, time }) => ({ date: mark(date), time: mark(time) })),
    dates: [...read.dates, ...datesBesideHeld].map(mark),
    times: read.times.map(mark),
  };
}

/**
 * The date and time stretches among the values read, each under its own
 * switch. A value in a markup range, an impossible date or time, a time
 * followed by a decimal fraction, and a clock time with no AM/PM in a cell
 * that holds a clock time with one ("12:45" in "12:45 - 1:30 PM") are held. A
 * held clock time with an AM/PM still counts for that last rule. When an ISO
 * date-time's date changes and its time is held, the date stretch covers the
 * separator too, and its separator field holds the separator's span, so the
 * table step writes a space in its place.
 */
function dateTimeStretches({ isoPairs, dates, times }, options) {
  const isDateChanged = (d) => options.simplifyDates && !d.isHeld && !d.impossible;
  const isTimeChanged = (t) => options.simplifyTimes && !t.isHeld && !t.impossible && !t.hasFraction;
  const hasMeridiemTime = times.some((t) => t.meridiem);
  const isoStretches = isoPairs.flatMap(({ date, time }) => {
    const timeStretches = isTimeChanged(time) ? [{ kind: 'time', ...time }] : [];
    if (!isDateChanged(date)) return timeStretches;
    if (timeStretches.length > 0) return [{ kind: 'date', ...date }, ...timeStretches];
    const separator = { start: date.end, end: date.end + 1 };
    return [{ kind: 'date', ...date, end: separator.end, separator }];
  });
  return [
    ...isoStretches,
    ...dates.filter(isDateChanged).map((d) => ({ kind: 'date', ...d })),
    ...times.filter((t) => isTimeChanged(t) && (t.meridiem || !hasMeridiemTime)).map((t) => ({ kind: 'time', ...t })),
  ];
}

/**
 * The masked ranges are one list, so a new kind of text whose numbers stay as
 * written is one more source here. The identifier scan reads the text with
 * each superscript span blanked, so a footnote marker right after a phone
 * number ("416-555-1234<sup>1</sup>") never joins its digits. classifyCell
 * holds, after this step, every number that overlaps a markup range, a date,
 * or a time.
 */
function extractSimplifyMatches(text, superscriptRanges) {
  const shapeText = blankRanges(text, superscriptRanges);
  const masked = [
    ...getQuoteMaskedRanges(text),
    ...getIdentifierMaskedRanges(shapeText),
    ...superscriptRanges,
    ...getEraYearMaskedRanges(text),
  ];
  return extractNumbersInText(text)
    .filter((m) => !overlapsMaskedRange(masked, m.index, m.index + m.numStr.length));
}

/**
 * The numbers of a cell that holds no date or time, read through the
 * whole-cell shapes first. A cell that is one number (a pure cell, a
 * bracketed number, or a unit number) gives one match over its digits alone,
 * so the write-back leaves a sign, a bracket, a currency sign, a percent
 * sign, a suffix, or a currency code where the page put it.
 */
function readNumberCell(text, input) {
  const { superscriptRanges = [], hasSuperscript = false, digitsSpanPieces = false } = input;
  // In a cell with a superscript, the text classifyCell reads joins base and
  // exponent digits ("10<sup>12</sup>" reads "1012"), which is not the text
  // the reader sees. So no whole-cell shape is tested against it, and
  // extraction masks each superscript span.
  if (hasSuperscript) return extractSimplifyMatches(text, superscriptRanges);

  // An identifier shape reads as a code, not a quantity, so the whole cell
  // stays as written. Checked before the number reader, which also reads a
  // digit run with a leading zero ("0012345678", "(0012345678)") as a number.
  if (matchIdentifierShape(text.trim(), digitsSpanPieces)) return [];

  const num = toNumber(text);
  if (num !== null) {
    const span = pureNumberSpan(text);
    return [{ numStr: span.numStr, num, index: span.index }];
  }

  // A unit number ("4.91tn", "CAD45.67") is one number with a suffix or a
  // currency code.
  const unit = matchUnitNumber(text);
  if (unit) return [unit];

  return extractSimplifyMatches(text, superscriptRanges);
}

function numberStretch(match) {
  return { kind: 'number', start: match.index, end: match.index + match.numStr.length, num: match.num };
}

/**
 * Classify a single cell and return a classification: { stretches }, the
 * cell's stretches in text order, each with its start and end in text:
 *
 *   { kind: 'number', start, end, num }
 *   { kind: 'date', start, end, ...the date findDates or findISODateTimes
 *     reads, and separator (see dateTimeStretches) }
 *   { kind: 'time', start, end, ...the time findClockTimes or
 *     findISODateTimes reads }
 *
 * Every number, date, and time in a cell is its own stretch under its own
 * switch. A value held stays as written and takes no stretch, and the
 * readers after it never read its characters. The column post-pass settles
 * the day and month of an ambiguous date stretch (isAmbiguousDate).
 *
 * A cell holds no stretch when it is out of range, under an exclusion
 * (getExclusionReason), wholly quoted, a web or email address, or an
 * identifier shape. A value is
 * held when it overlaps a markup range or its switch is off. A date or time
 * is also held when it is impossible (see dateTimeStretches), and a number
 * when a currency or percent sign whose switch is off touches its digits
 * (touchesSwitchedOffSign). The placement step adds split: true to a
 * classification whose split stretches it removes.
 */
function classifyCell(input, options) {
  const { text, rowIndex, columnIndex, ranges, markupRanges = [], superscriptRanges = [] } = input;

  if (!isInRanges(rowIndex, columnIndex, ranges)) return { stretches: [] };
  if (getExclusionReason(columnIndex, options, rowIndex)) return { stretches: [] };
  if (isWholeCellQuoted(text.trim())) return { stretches: [] };
  // A web or email address that fills the cell holds before any date or time
  // is read: its path or query may hold one ("https://example.com/2020-07-21/
  // post"), and a changed date or time breaks the address.
  if (isWebOrEmailAddressCell(text.trim())) return { stretches: [] };

  const read = readDatesAndTimesHoldingMarkup(text, superscriptRanges, markupRanges);
  const dateTimeSpans = valuesRead(read);
  const heldRanges = [...markupRanges, ...dateTimeSpans];
  const numbers = dateTimeSpans.length > 0
    ? extractSimplifyMatches(text, superscriptRanges)
    : readNumberCell(text, input);
  const numberStretches = numbers
    .filter((m) => !overlapsMaskedRange(heldRanges, m.index, m.index + m.numStr.length))
    .filter((m) => !touchesSwitchedOffSign(text, m, options))
    .map(numberStretch);
  const stretches = [...dateTimeStretches(read, options), ...numberStretches]
    .sort((a, b) => a.start - b.start);
  return { stretches };
}

/**
 * Decide how to read a column's ambiguous N1/N2/Y dates (e.g. "03/04/2020"),
 * given every ambiguous date's {n1, n2} found in that column. Any n > 12 in
 * one position rules out that position being the month, so a lone violator
 * pins the whole column's format ('month-first' or 'day-first'); violators on
 * both sides make the column unsafe to guess ('mixed'); no violator leaves it
 * genuinely ambiguous ('ambiguous').
 */
function pickDateFormatHint(ambiguousList) {
  let hasN1gt12 = false;
  let hasN2gt12 = false;
  for (const { n1, n2 } of ambiguousList) {
    if (n1 > 12) hasN1gt12 = true;
    if (n2 > 12) hasN2gt12 = true;
  }
  if (hasN1gt12 && !hasN2gt12) return 'day-first';
  if (hasN2gt12 && !hasN1gt12) return 'month-first';
  if (hasN1gt12 && hasN2gt12) return 'mixed';
  return 'ambiguous';
}

// ---- chrome-extension/lib/dr-simplify/table.js ----

